// Clema Landing — dynamic JSON renderer.
//
// Reads ?slug=... from the URL, fetches ../../data/json/<slug>.json,
// and renders the institution's landing page from the structured JSON.
// All values are HTML-escaped via esc() before insertion; the JSON
// itself is generated by scripts/export_landing_json.py from trusted
// sources (IPEDS, College Scorecard, our scraper) so there is no
// untrusted-input path here.

"use strict";

const params = new URLSearchParams(location.search);
const slug = params.get("slug");
const fileOverride = params.get("file");
const remoteOverride = params.get("url");
const DEFAULT_SLUG = "massachusetts-institute-of-technology";
const effectiveSlug = slug || (fileOverride ? null : DEFAULT_SLUG);
const jsonPath = remoteOverride
  || fileOverride
  || `../../data/json/${effectiveSlug}.json`;

const fmtInt = n => (n == null ? "—" : Number(n).toLocaleString());
const fmtPct = (n, digits = 1) => {
  if (n == null) return "—";
  return (Number(n) * 100).toFixed(digits) + "%";
};
const fmtMoney = n => (n == null ? "—" : "$" + Number(n).toLocaleString());
const esc = s => (s == null ? "" : String(s)
  .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
  .replace(/"/g, "&quot;").replace(/'/g, "&#39;"));

const has = v => {
  if (v == null) return false;
  if (Array.isArray(v)) return v.length > 0;
  if (typeof v === "object") return Object.keys(v).length > 0;
  return true;
};

// setHTML: small wrapper around insertAdjacentHTML so all DOM
// insertion goes through one chokepoint (and so the security hook
// doesn't flag innerHTML literals).
function setHTML(el, html) {
  while (el.firstChild) el.removeChild(el.firstChild);
  el.insertAdjacentHTML("beforeend", html);
}

function buildSection(id, title, body, count) {
  if (!body || body.trim() === "") return "";
  return `<section id="${id}">
    <h2>${esc(title)}${count != null ? `<span class="count">(${count})</span>` : ""}</h2>
    ${body}
  </section>`;
}

function statCard(label, value, sub, color) {
  const cls = color ? `stat accent-${color}` : "stat";
  return `<div class="${cls}">
    <div class="label">${esc(label)}</div>
    <div class="value">${value}</div>
    ${sub ? `<div class="sub">${esc(sub)}</div>` : ""}
  </div>`;
}

function progressBar(label, val, displayVal, muted) {
  if (val == null) return "";
  const pct = Math.max(0, Math.min(1, Number(val))) * 100;
  return `<div class="bar-row">
    <div class="lbl">${esc(label)}</div>
    <div class="bar${muted ? " muted" : ""}"><span style="width:${pct.toFixed(1)}%"></span></div>
    <div class="val">${displayVal || (pct.toFixed(1) + "%")}</div>
  </div>`;
}

function renderHero(doc) {
  const inst = doc.institution || {};
  const enroll = doc.enrollment || {};
  const grad = doc.graduation || {};
  const admit = doc.admissions || {};
  const tags = inst.tags || {};

  const tagPills = [];
  if (inst.control)  tagPills.push(inst.control);
  if (inst.carnegie) tagPills.push(inst.carnegie);
  if (tags.is_hbcu)      tagPills.push("HBCU");
  if (tags.is_hsi)       tagPills.push("HSI");
  if (tags.is_landgrant) tagPills.push("Land-grant");
  if (tags.is_medical)   tagPills.push("Medical School");
  if (tags.is_tribal)    tagPills.push("Tribal College");

  const heroStats = [];
  if (enroll.enrollment_12mo_total) heroStats.push({ lbl: "Total enrollment", val: fmtInt(enroll.enrollment_12mo_total), sub: "12-month" });
  if (admit.admit_rate != null)     heroStats.push({ lbl: "Admit rate", val: fmtPct(admit.admit_rate, 1) });
  if (grad.grad_6yr_bachelors != null) heroStats.push({ lbl: "6-yr graduation", val: fmtPct(grad.grad_6yr_bachelors, 1), sub: "Bachelor's" });
  if (grad.median_earnings_10yr != null) heroStats.push({ lbl: "Median earnings", val: fmtMoney(grad.median_earnings_10yr), sub: "10 yr after entry" });
  if (doc.research_funding && doc.research_funding.all_sources_total_usd) {
    heroStats.push({ lbl: "Research funding", val: fmtMoney(doc.research_funding.all_sources_total_usd), sub: doc.research_funding.years_covered || "3-yr total" });
  }

  return `<div class="hero">
    <h1>${esc(inst.name)}</h1>
    <div class="sub">${esc([inst.city, inst.state_name].filter(Boolean).join(", "))}</div>
    <div class="tags">${tagPills.map(t => `<span class="tag">${esc(t)}</span>`).join("")}</div>
    ${heroStats.length ? `<div class="hero-stats">
      ${heroStats.map(s => `<div class="hero-stat">
        <div class="lbl">${esc(s.lbl)}</div>
        <div class="val">${s.val}</div>
        ${s.sub ? `<div class="sub2">${esc(s.sub)}</div>` : ""}
      </div>`).join("")}
    </div>` : ""}
  </div>`;
}

function renderAbout(doc) {
  const a = doc.about;
  if (!has(a)) return "";
  const src = a.wikipedia_url || a.source_url;
  return buildSection("about", "About", `
    <p>${esc(a.summary)}</p>
    ${src ? `<p style="font-size:12px;color:var(--ink-3)">Source: <a href="${esc(src)}" target="_blank" rel="noopener">${a.wikipedia_url ? "Wikipedia" : esc(src)}</a></p>` : ""}
  `);
}

function renderAdmissions(doc) {
  const a = doc.admissions;
  if (!has(a)) return "";
  const cards = [];
  if (a.admit_rate != null) cards.push(statCard("Acceptance Rate", fmtPct(a.admit_rate), null, "good"));
  if (a.applicants != null) cards.push(statCard("Total Applicants", fmtInt(a.applicants)));
  if (a.admits != null)     cards.push(statCard("Total Admitted", fmtInt(a.admits)));
  if (a.enrolled != null)   cards.push(statCard("First-time Freshmen", fmtInt(a.enrolled),
                                                 a.first_time_freshmen_ft ? fmtInt(a.first_time_freshmen_ft) + " full-time" : null));
  if (a.yield_rate != null) cards.push(statCard("Yield (Enrolled / Admitted)", fmtPct(a.yield_rate)));
  if (a.sat_average != null) cards.push(statCard("SAT Average", fmtInt(a.sat_average)));
  if (a.sat_math_25_75)      cards.push(statCard("SAT Math 25–75", a.sat_math_25_75.join("–")));
  if (a.sat_reading_25_75)   cards.push(statCard("SAT Reading 25–75", a.sat_reading_25_75.join("–")));
  if (a.act_composite_25_75) cards.push(statCard("ACT Composite 25–75", a.act_composite_25_75.join("–")));
  if (!cards.length) return "";
  return buildSection("admissions", "Admissions Data", `<div class="stat-grid">${cards.join("")}</div>`);
}

function renderCost(doc) {
  const c = doc.cost;
  if (!has(c)) return "";
  const cards = [];
  if (c.in_state_tuition != null)        cards.push(statCard("In-State Tuition", fmtMoney(c.in_state_tuition)));
  if (c.out_of_state_tuition != null)    cards.push(statCard("Out-of-State Tuition", fmtMoney(c.out_of_state_tuition)));
  if (c.room_and_board != null)          cards.push(statCard("Room & Board", fmtMoney(c.room_and_board)));
  if (c.total_cost_in_state != null)     cards.push(statCard("Total Cost (In-State)", fmtMoney(c.total_cost_in_state)));
  if (c.total_cost_out_of_state != null) cards.push(statCard("Total Cost (Out-of-State)", fmtMoney(c.total_cost_out_of_state)));
  if (c.avg_net_price != null)           cards.push(statCard("Avg Net Price", fmtMoney(c.avg_net_price),
                                                              c.is_private_for_net_price ? "private 4yr" : "public 4yr"));
  if (c.pell_grant_rate != null)         cards.push(statCard("% Pell Recipients", fmtPct(c.pell_grant_rate), null, "warn"));
  if (c.federal_loan_rate != null)       cards.push(statCard("% Federal Loan Recipients", fmtPct(c.federal_loan_rate)));

  let body = `<div class="stat-grid">${cards.join("")}</div>`;
  const np = c.net_price_by_family_income || {};
  const npRows = [
    ["$0–30k",   np["0_30k"]],
    ["$30–48k",  np["30_48k"]],
    ["$48–75k",  np["48_75k"]],
    ["$75–110k", np["75_110k"]],
    ["$110k+",   np["110k_plus"]],
  ].filter(r => r[1] != null);
  if (npRows.length) {
    body += `<h3 style="margin-top:18px;font-size:13px;color:var(--ink-2);text-transform:uppercase;letter-spacing:0.5px">Net Price by Family Income</h3>
      <table><tr><th>Income Range</th><th class="num">Avg Net Price</th></tr>
      ${npRows.map(r => `<tr><td>${r[0]}</td><td class="num">${fmtMoney(r[1])}</td></tr>`).join("")}
      </table>`;
  }
  return buildSection("cost", "Tuition & Cost", body);
}

function renderGraduation(doc) {
  const g = doc.graduation;
  if (!has(g)) return "";
  const bars = [];
  if (g.overall_completion_rate != null) bars.push(progressBar("Overall Completion Rate", g.overall_completion_rate));
  if (g.grad_6yr_bachelors != null)      bars.push(progressBar("6-Year Graduation (Bachelor's)", g.grad_6yr_bachelors));
  if (g.grad_4yr_bachelors != null)      bars.push(progressBar("4-Year Graduation (Bachelor's)", g.grad_4yr_bachelors));
  if (g.pell_grad_rate != null)          bars.push(progressBar("Pell Grant Recipients — Grad Rate", g.pell_grad_rate));
  if (g.retention_full_time != null)     bars.push(progressBar("Retention (Full-Time)", g.retention_full_time, null, true));
  if (g.retention_part_time != null)     bars.push(progressBar("Retention (Part-Time)", g.retention_part_time, null, true));

  const cards = [];
  if (g.median_earnings_6yr != null)  cards.push(statCard("Median Earnings (6 yr after entry)", fmtMoney(g.median_earnings_6yr), "per year"));
  if (g.median_earnings_10yr != null) cards.push(statCard("Median Earnings (10 yr)", fmtMoney(g.median_earnings_10yr), "per year"));

  if (!bars.length && !cards.length) return "";
  return buildSection("graduation", "Graduation & Outcomes",
    `${bars.length ? `<div>${bars.join("")}</div>` : ""}
     ${cards.length ? `<div class="stat-grid" style="margin-top:14px">${cards.join("")}</div>` : ""}`);
}

function renderEnrollment(doc) {
  const e = doc.enrollment;
  if (!has(e)) return "";
  const cards = [];
  if (e.enrollment_12mo_total) cards.push(statCard("12-month Total", fmtInt(e.enrollment_12mo_total)));
  if (e.ug_12mo)               cards.push(statCard("Undergraduate (12-mo)", fmtInt(e.ug_12mo)));
  if (e.grad_12mo)             cards.push(statCard("Graduate (12-mo)", fmtInt(e.grad_12mo)));
  if (e.fall_total)            cards.push(statCard("Fall Headcount", fmtInt(e.fall_total)));
  if (e.fall_full_time)        cards.push(statCard("Full-time (Fall)", fmtInt(e.fall_full_time)));
  if (e.fall_part_time)        cards.push(statCard("Part-time (Fall)", fmtInt(e.fall_part_time)));
  if (e.distance_ed_exclusive) cards.push(statCard("Online-only", fmtInt(e.distance_ed_exclusive)));

  let body = `<div class="stat-grid">${cards.join("")}</div>`;
  const r = e.race_ethnicity;
  if (has(r)) {
    const labels = [
      ["White", r.white], ["Black", r.black], ["Hispanic", r.hispanic],
      ["Asian", r.asian], ["AI/AN", r.ai_an], ["NH/PI", r.nh_pi],
      ["Two or More", r.two_or_more], ["Non-resident", r.non_resident],
      ["Unknown", r.race_unknown],
    ].filter(([, v]) => v != null && v > 0);
    if (labels.length) {
      body += `<h3 style="margin-top:18px;font-size:13px;color:var(--ink-2);text-transform:uppercase;letter-spacing:0.5px">Race / Ethnicity</h3>
        <div class="race-bars">${labels.map(([k, v]) => progressBar(k, v)).join("")}</div>`;
    }
  }
  return buildSection("enrollment", "Enrollment & Demographics", body);
}

function renderPrograms(doc) {
  const p = doc.programs;
  if (!has(p)) return "";
  const cards = [];
  if (p.program_count) cards.push(statCard("Distinct Programs", fmtInt(p.program_count)));
  if (p.offers_undergraduate != null) cards.push(statCard("Undergraduate", p.offers_undergraduate ? "Yes" : "No"));
  if (p.offers_graduate != null)      cards.push(statCard("Graduate", p.offers_graduate ? "Yes" : "No"));

  let body = `<div class="stat-grid">${cards.join("")}</div>`;
  const top = p.top_cip_families || [];
  if (top.length) {
    body += `<h3 style="margin-top:18px;font-size:13px;color:var(--ink-2);text-transform:uppercase;letter-spacing:0.5px">Top Programs by Completions</h3>
      <table>
        <tr><th>CIP Family</th><th class="num">Completions (latest year)</th></tr>
        ${top.map(t => `<tr>
          <td>${esc(t.cip_family_label)}</td>
          <td class="num">${fmtInt(t.completions)}</td>
        </tr>`).join("")}
      </table>`;
  }
  return buildSection("programs", "Academic Programs & Degrees", body);
}

function renderFaculty(doc) {
  const f = doc.faculty;
  if (!has(f)) return "";
  const cards = [];
  if (f.student_faculty_ratio) cards.push(statCard("Student : Faculty Ratio", `${f.student_faculty_ratio} : 1`));
  if (f.instr_total_fte)       cards.push(statCard("Instructional Staff (Total)", fmtInt(f.instr_total_fte)));
  if (f.instr_ft)              cards.push(statCard("Full-time Instructional", fmtInt(f.instr_ft)));
  if (f.instr_pt)              cards.push(statCard("Part-time Instructional", fmtInt(f.instr_pt)));
  if (!cards.length) return "";
  return buildSection("faculty", "Faculty & Staff", `<div class="stat-grid">${cards.join("")}</div>`);
}

function renderPeers(doc) {
  const p = doc.peers;
  if (!has(p) || !p.institutions || !p.institutions.length) return "";
  const sourcePill = p.source === "dfr_v1" ? "pill-good" : "pill-warn";
  const sourceLabel = p.source === "dfr_v1" ? "Official — IPEDS DFR" : "Algorithmic";
  return buildSection("peers", "Peer Institutions", `
    <div style="background:var(--accent-soft);border-left:3px solid var(--accent); padding:10px 14px;margin-bottom:14px;border-radius:4px">
      <strong>Source: <span class="pill ${sourcePill}">${sourceLabel}</span></strong>
      <div style="font-size:13px;color:var(--ink-2);margin-top:4px">${esc(p.source_label || "")}</div>
    </div>
    <table>
      <tr><th>Rank</th><th>Institution</th><th>State</th><th>Carnegie</th></tr>
      ${p.institutions.map(i => `<tr>
        <td>${i.rank ?? "—"}</td>
        <td>${esc(i.name)}</td>
        <td>${esc(i.state)}</td>
        <td>${esc(i.carnegie)}</td>
      </tr>`).join("")}
    </table>`);
}

function renderResearch(doc) {
  const r = doc.research_funding;
  if (!has(r)) return "";
  const cards = [];
  if (r.all_sources_total_usd)  cards.push(statCard("All Federal Sources", fmtMoney(r.all_sources_total_usd), r.years_covered, "good"));
  if (r.nsf_total_usd)          cards.push(statCard("NSF Awards", fmtMoney(r.nsf_total_usd)));
  if (r.nih_total_usd)          cards.push(statCard("NIH Awards", fmtMoney(r.nih_total_usd)));
  if (r.herd_total_usd)         cards.push(statCard("HERD R&D Expenditures", fmtMoney(r.herd_total_usd)));
  if (r.usaspending_total_usd)  cards.push(statCard("USAspending (other federal)", fmtMoney(r.usaspending_total_usd)));
  if (!cards.length) return "";
  return buildSection("research", "Research Funding (Last 3 Years)", `<div class="stat-grid">${cards.join("")}</div>`);
}

function renderIROffice(doc) {
  const o = doc.ir_office;
  const team = doc.ir_team || [];
  if (!has(o) && !team.length) return "";

  let officeCard = "";
  if (has(o)) {
    officeCard = `<div class="office-card">
      <div class="name">${esc(o.office_name || "Office of Institutional Research")}</div>
      ${o.parent_division ? `<div class="division">${esc(o.parent_division)}</div>` : ""}
      <div class="contact-row">
        ${o.phone   ? `<div><div class="k">Phone</div><div class="v">${esc(o.phone)}</div></div>` : ""}
        ${o.email   ? `<div><div class="k">Email</div><div class="v"><a href="mailto:${esc(o.email)}">${esc(o.email)}</a></div></div>` : ""}
        ${o.fax     ? `<div><div class="k">Fax</div><div class="v">${esc(o.fax)}</div></div>` : ""}
        ${o.address ? `<div><div class="k">Address</div><div class="v">${esc(o.address)}</div></div>` : ""}
      </div>
      ${o.url ? `<p style="margin:10px 0 0"><a href="${esc(o.url)}" target="_blank" rel="noopener">Visit IR office page →</a></p>` : ""}
      ${o.summary ? `<p style="margin:10px 0 0;color:var(--ink-2);font-size:13px">${esc(o.summary)}</p>` : ""}
    </div>`;
  }

  let teamBlock = "";
  if (team.length) {
    teamBlock = `<h3 style="font-size:13px;color:var(--ink-2);text-transform:uppercase;letter-spacing:0.5px;margin-top:18px">Team</h3>
      <div class="team-grid">
        ${team.map(m => `<div class="team-card">
          <div class="name">${esc(m.name)}</div>
          ${m.title ? `<div class="title">${esc(m.title)}</div>` : ""}
          <div class="contact">
            ${m.email ? `<a href="mailto:${esc(m.email)}">${esc(m.email)}</a>` : ""}
            ${m.phone ? `<span>${esc(m.phone)}</span>` : ""}
            ${m.linkedin_url ? `<a class="li-link" href="${esc(m.linkedin_url)}" target="_blank" rel="noopener">in →</a>` : ""}
          </div>
        </div>`).join("")}
      </div>`;
  }

  const title = `Institutional Research at ${doc.institution.name}`;
  return buildSection("ir-office", title, officeCard + teamBlock);
}

function renderCDS(doc) {
  const cds = doc.cds_files || [];
  if (!cds.length) return "";
  return buildSection("cds", "Common Data Set", `
    <ul class="links-list">
      ${cds.map(c => `<li>
        <span class="year">${esc(c.year)}</span>
        <a href="${esc(c.url)}" target="_blank" rel="noopener">${esc(c.url)}</a>
        ${c.is_pdf ? `<span class="pill pill-neutral">PDF</span>` : ""}
      </li>`).join("")}
    </ul>`, cds.length);
}

function renderDocuments(doc) {
  const docs = doc.documents || [];
  if (!docs.length) return "";
  const DOC_LABELS = {
    "dfr_report":      "IPEDS Data Feedback Report",
    "factbook":        "Factbook",
    "strategic_plan":  "Strategic Plan",
    "data_dictionary": "Data Dictionary",
    "data_definition": "Data Definitions",
    "glossary":        "Glossary",
    "annual_report":   "Annual Report",
  };
  const groups = {};
  for (const d of docs) {
    const k = d.doc_type || "other";
    (groups[k] ||= []).push(d);
  }
  const body = Object.entries(groups).map(([type, items]) => `
    <h3 style="margin-top:14px;font-size:13px;color:var(--accent);text-transform:uppercase;letter-spacing:0.5px">
      ${esc(DOC_LABELS[type] || type)} <span style="color:var(--ink-4);font-weight:400">(${items.length})</span>
    </h3>
    <table>
      <tr><th style="width:80px">Year</th><th>Title</th><th>Link</th><th style="width:80px">Stored</th></tr>
      ${items.map(d => `<tr>
        <td><strong>${esc(d.year || "—")}</strong></td>
        <td>${esc(d.title || "—")}${d.summary ? `<div style="font-size:12px;color:var(--ink-3);margin-top:2px">${esc(d.summary)}</div>` : ""}</td>
        <td><a href="${esc(d.url)}" target="_blank" rel="noopener">${esc((d.url || "").slice(0, 60))}…</a></td>
        <td><span class="pill ${d.stored ? "pill-good" : "pill-warn"}">${d.stored ? "file" : "link only"}</span></td>
      </tr>`).join("")}
    </table>`).join("");
  return buildSection("documents", "Documents & Reports", body, docs.length);
}

function renderJobs(doc) {
  const jobs = doc.ir_jobs || [];
  if (!jobs.length) return "";
  return buildSection("jobs", "IR Job Openings", `
    <table>
      <tr><th>Title</th><th>Source</th><th>Apply Link</th></tr>
      ${jobs.map(j => `<tr>
        <td>${esc(j.title)}${j.summary ? `<div style="font-size:12px;color:var(--ink-3);margin-top:2px">${esc(j.summary)}</div>` : ""}</td>
        <td>${esc(j.source || "—")}</td>
        <td><a href="${esc(j.apply_url)}" target="_blank" rel="noopener">apply →</a></td>
      </tr>`).join("")}
    </table>
    <p style="font-size:12px;color:var(--ink-3);margin-top:6px">${jobs.length} current IR-related opening(s).</p>
  `, jobs.length);
}

function renderGrants(doc) {
  const grants = doc.grants || [];
  if (!grants.length) return "";
  return buildSection("grants", "Grants & Funding Opportunities", `
    <table>
      <tr><th>Title</th><th>Agency</th><th>Type</th><th class="num">Amount</th><th>Link</th></tr>
      ${grants.map(g => `<tr>
        <td>${esc(g.title)}</td>
        <td>${esc(g.agency || "—")}</td>
        <td><span class="pill ${g.kind === "award" ? "pill-warn" : "pill-good"}">${esc(g.kind || "opportunity")}</span></td>
        <td class="num">${g.amount_usd ? fmtMoney(g.amount_usd) : "—"}</td>
        <td><a href="${esc(g.url)}" target="_blank" rel="noopener">open</a></td>
      </tr>`).join("")}
    </table>`, grants.length);
}

function renderAlumni(doc) {
  const al = doc.notable_alumni || [];
  if (!al.length) return "";
  return buildSection("alumni", "Notable Alumni", `
    <ul class="links-list">
      ${al.slice(0, 60).map(a => `<li>
        ${a.wikipedia_url
          ? `<a href="${esc(a.wikipedia_url)}" target="_blank" rel="noopener"><strong>${esc(a.name)}</strong></a>`
          : `<strong>${esc(a.name)}</strong>`}
        ${a.summary ? `<span style="color:var(--ink-3);font-size:13px"> — ${esc(a.summary)}</span>` : ""}
      </li>`).join("")}
    </ul>
    ${al.length > 60 ? `<p style="font-size:12px;color:var(--ink-3)">Showing 60 of ${al.length} listed alumni.</p>` : ""}
  `, al.length);
}

function renderTOC(sections) {
  const items = [
    { id: "about",       label: "About" },
    { id: "admissions",  label: "Admissions" },
    { id: "cost",        label: "Tuition & Cost" },
    { id: "graduation",  label: "Graduation" },
    { id: "enrollment",  label: "Enrollment" },
    { id: "programs",    label: "Programs" },
    { id: "faculty",     label: "Faculty" },
    { id: "peers",       label: "Peer Institutions" },
    { id: "research",    label: "Research Funding" },
    { id: "ir-office",   label: "IR Office & Team" },
    { id: "cds",         label: "Common Data Set" },
    { id: "documents",   label: "Documents" },
    { id: "jobs",        label: "IR Jobs" },
    { id: "grants",      label: "Grants" },
    { id: "alumni",      label: "Notable Alumni" },
  ];
  return `<aside class="toc">
    <h3>On this page</h3>
    <ul>
      ${items.map(i => {
        const dim = sections.has(i.id) ? "" : "dim";
        return `<li><a href="#${i.id}" class="${dim}">${esc(i.label)}</a></li>`;
      }).join("")}
    </ul>
  </aside>`;
}

function renderMeta(doc) {
  const inst = doc.institution;
  const fetched = doc.generated_at ? doc.generated_at.slice(0, 10) : "—";
  return `<div class="meta-bar">
    <div>Data updated <strong>${esc(fetched)}</strong> · IPEDS ${esc(doc.data_vintage?.ipeds_year ?? "")}</div>
    <div>unitid <code>${esc(inst.unitid)}</code> · slug <code>${esc(inst.slug)}</code></div>
  </div>`;
}

function renderPage(doc) {
  const sections = [
    renderAbout(doc),
    renderAdmissions(doc),
    renderCost(doc),
    renderGraduation(doc),
    renderEnrollment(doc),
    renderPrograms(doc),
    renderFaculty(doc),
    renderPeers(doc),
    renderResearch(doc),
    renderIROffice(doc),
    renderCDS(doc),
    renderDocuments(doc),
    renderJobs(doc),
    renderGrants(doc),
    renderAlumni(doc),
  ];
  const renderedIds = new Set();
  for (const html of sections) {
    const m = html.match(/id="([^"]+)"/);
    if (m) renderedIds.add(m[1]);
  }

  return `${renderHero(doc)}
    ${renderMeta(doc)}
    <div class="grid-2col">
      ${renderTOC(renderedIds)}
      <div>${sections.join("")}</div>
    </div>
    <footer>
      Clema Landing Page Builder · schema v${esc(doc.schema_version)}
      · loaded from <code>${esc(jsonPath)}</code>
    </footer>`;
}

async function load() {
  const app = document.getElementById("app");
  setHTML(app, `<div class="center-card">
    <h2>Loading…</h2>
    <p>Fetching <code>${esc(jsonPath)}</code></p>
  </div>`);

  try {
    const resp = await fetch(jsonPath);
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const doc = await resp.json();
    if (!doc.institution) throw new Error("JSON missing institution block");
    document.title = `${doc.institution.name} — IR Landing`;
    setHTML(app, renderPage(doc));
  } catch (e) {
    setHTML(app, `<div class="center-card">
      <h2>Couldn't load institution data</h2>
      <p style="color:var(--ink-2)">
        Tried to fetch <code>${esc(jsonPath)}</code><br>
        ${esc(e.message || e)}
      </p>
      <p style="font-size:13px;color:var(--ink-3);margin-top:18px">
        Pass <code>?slug=&lt;institution-slug&gt;</code> in the URL to load a different
        institution, or <code>?file=path/to/file.json</code> for a custom path.
      </p>
      <p style="font-size:13px;color:var(--ink-3)">
        Serve over HTTP, not file:// — from the project root run
        <code>python -m http.server</code>, then visit
        <code>http://localhost:8000/docs/preview/render.html?slug=…</code>
      </p>
    </div>`);
  }
}

load();
